// Supabase data access for Study Hopper — NOT generated by Figma Make.
import { supabase } from "./supabase";
import { DEFAULT_CENTER_LATLNG, type LatLng, type PlaceSpot } from "./places";

export type DbSpot = {
  id: string;
  name: string;
  latitude: number;
  longitude: number;
  address: string | null;
  place_id: string | null;
  avg_rating: number | string | null;
  rating_count: number;
  noise: "quiet" | "chatter" | "loud" | null;
  outlets: "every-table" | "few" | "none" | null;
  wifi: "slow" | "med" | "fast" | null;
  seating: number | null;
  price: "$" | "$$" | "$$$" | null;
  price_note: string | null;
  hours: string | null;
  open_late: boolean | null;
  tags: string[] | null;
  summary: string | null;
  busiest_hours: string | null;
};

export type LeaderboardRow = {
  rank: number;
  user_id: string;
  display_name: string;
  total_minutes: number;
  total_hours: number;
  session_count: number;
};

export type StudySessionRow = {
  id: string;
  user_id: string;
  display_name: string;
  spot_name: string;
  started_at: string;
  duration_minutes: number;
  note: string | null;
};

/** A spot as the app uses it, plus the Supabase uuid. */
export type CommunitySpot = PlaceSpot & { dbId: string };

function client() {
  if (!supabase) throw new Error("Supabase is not configured");
  return supabase;
}

const NOISE_LABEL = { quiet: "quiet", chatter: "a bit of chatter", loud: "loud" } as const;
const OUTLET_LABEL = { "every-table": "outlets at every table", few: "a few outlets", none: "almost no outlets" } as const;
const WIFI_LABEL = { fast: "fast wifi", med: "medium wifi", slow: "slow wifi" } as const;

const LIBRARY_IMAGE =
  "https://images.unsplash.com/photo-1694315643310-5a42072aa014?crop=entropy&cs=tinysrgb&fit=crop&fm=jpg&q=85&w=900&h=700";
const COFFEE_IMAGE =
  "https://images.unsplash.com/photo-1758610605872-3195caed0bdd?crop=entropy&cs=tinysrgb&fit=crop&fm=jpg&q=85&w=900&h=700";

function numericId(seed: string) {
  let hash = 0;
  for (let i = 0; i < seed.length; i++) hash = (hash * 31 + seed.charCodeAt(i)) | 0;
  return 1_000_000 + Math.abs(hash);
}

/** Rough % position for the hand-drawn fallback map (real map uses `location`). */
function fakePosition({ lat, lng }: LatLng) {
  const clamp = (n: number) => Math.min(90, Math.max(10, n));
  return {
    left: `${clamp(50 + ((lng - DEFAULT_CENTER_LATLNG.lng) / 0.02) * 100)}%`,
    top: `${clamp(50 - ((lat - DEFAULT_CENTER_LATLNG.lat) / 0.014) * 100)}%`,
  };
}

export function communityHighlights(row: DbSpot): string[] {
  const labels: (string | null)[] = [
    row.noise ? NOISE_LABEL[row.noise] : null,
    row.outlets ? OUTLET_LABEL[row.outlets] : null,
    row.wifi ? WIFI_LABEL[row.wifi] : null,
  ];
  return labels.filter((value): value is string => Boolean(value));
}

export function toSpot(row: DbSpot): CommunitySpot {
  const location = { lat: row.latitude, lng: row.longitude };
  const isLibrary = /librar|reading room/i.test(`${row.name} ${(row.tags ?? []).join(" ")}`);
  const type: PlaceSpot["type"] = isLibrary ? "library" : "coffee";
  const highlights = communityHighlights(row);
  return {
    id: numericId(row.place_id ?? row.id),
    dbId: row.id,
    placeId: row.place_id ?? undefined,
    name: row.name,
    area: row.address?.split(",")[1]?.trim() || "Nearby",
    walk: "nearby",
    type,
    tags: row.tags?.length ? row.tags : [type === "library" ? "library" : "cafe"],
    note: row.summary ?? row.price_note ?? "Rated by the Study Hopper community",
    image: isLibrary ? LIBRARY_IMAGE : COFFEE_IMAGE,
    color: isLibrary ? "#475f9b" : "#e95743",
    position: fakePosition(location),
    rating: Number(row.avg_rating ?? 0),
    reviews: row.rating_count ?? 0,
    highlights: highlights.length ? highlights : ["community pick"],
    openEarly: false,
    openLate: Boolean(row.open_late),
    hours: row.hours ?? "hours unknown",
    address: row.address?.split(",")[0]?.trim() ?? "",
    location,
  };
}

export async function fetchSpots(): Promise<CommunitySpot[]> {
  const { data, error } = await client().from("spots").select("*").order("name").limit(500);
  if (error) throw error;
  return (data as DbSpot[]).map(toSpot);
}

/**
 * Merge Google Places results with Supabase community spots (matched by place_id).
 * Community ratings / noise / outlets / wifi / summary win; Places keeps photo, walk time, live hours.
 * Supabase spots with no Places match are still included (they carry lat/lng).
 */
export function mergeSpots(places: PlaceSpot[], community: CommunitySpot[]): PlaceSpot[] {
  const byPlaceId = new Map(community.filter((spot) => spot.placeId).map((spot) => [spot.placeId!, spot]));
  const used = new Set<string>();
  const merged: PlaceSpot[] = places.map((place) => {
    const match = place.placeId ? byPlaceId.get(place.placeId) : undefined;
    if (!match) return place;
    used.add(match.dbId);
    const hasRatings = match.reviews > 0;
    return {
      ...place,
      id: match.id,
      dbId: match.dbId,
      rating: hasRatings ? match.rating : place.rating,
      reviews: hasRatings ? match.reviews : place.reviews,
      highlights: match.highlights[0] !== "community pick" ? match.highlights : place.highlights,
      tags: Array.from(new Set([...match.tags, ...place.tags])),
      note: match.note || place.note,
      openLate: place.openLate || match.openLate,
      hours: place.hours === "hours unknown" ? match.hours : place.hours,
    } as PlaceSpot;
  });
  return [...merged, ...community.filter((spot) => !used.has(spot.dbId))];
}

// --- Writes (all require a signed-in guest; RLS + the RPCs enforce auth.uid()) ---

type ReviewNumbers = { wifi?: number | null; outlets?: number | null; noise?: number | null };

export async function addRating(spotId: string, score: number, review: ReviewNumbers = {}, note?: string) {
  const { data, error } = await client().rpc("add_rating", {
    target_cafe_id: spotId,
    target_score: score,
    target_wifi: review.wifi ?? null,
    target_outlets: review.outlets ?? null,
    target_noise: review.noise ?? null,
    target_note: note?.trim() || null,
  });
  if (error) throw error;
  return data;
}

export async function addRankedCafe(input: {
  name: string;
  location: LatLng;
  placeId: string;
  score: number;
  address?: string;
  review?: ReviewNumbers;
  note?: string;
  hours?: string;
  openLate?: boolean | null;
  seating?: number | null;
  price?: string | null;
  tags?: string[];
}) {
  const price = input.price && ["$", "$$", "$$$"].includes(input.price) ? input.price : input.price ? "$$$" : null;
  const { data, error } = await client().rpc("add_ranked_cafe", {
    cafe_name: input.name,
    cafe_latitude: input.location.lat,
    cafe_longitude: input.location.lng,
    cafe_place_id: input.placeId,
    target_score: input.score,
    cafe_address: input.address ?? null,
    target_wifi: input.review?.wifi ?? null,
    target_outlets: input.review?.outlets ?? null,
    target_noise: input.review?.noise ?? null,
    target_note: input.note?.trim() || null,
    cafe_hours: input.hours ?? null,
    cafe_open_late: input.openLate ?? null,
    cafe_seating: input.seating && input.seating > 0 ? input.seating : null,
    cafe_price: price,
    cafe_price_note: null,
    cafe_tags: input.tags ?? null,
  });
  if (error) throw error;
  return data as DbSpot;
}

export async function logStudySession(hours: number, spotId?: string | null, note?: string, placeName?: string) {
  const { data, error } = await client().rpc("log_study_session", {
    hours,
    spot_id: spotId ?? null,
    started_at: new Date().toISOString(),
    note: note?.trim() || null,
    place_name: placeName?.trim() || null,
  });
  if (error) throw error;
  return data;
}

export async function getLeaderboard(limit = 10): Promise<LeaderboardRow[]> {
  const { data, error } = await client().rpc("get_study_leaderboard", { result_limit: limit });
  if (error) throw error;
  return (data ?? []) as LeaderboardRow[];
}

export async function getRecentSessions(limit = 20): Promise<StudySessionRow[]> {
  const { data, error } = await client().rpc("get_recent_study_sessions", { result_limit: limit });
  if (error) throw error;
  return (data ?? []) as StudySessionRow[];
}

/** The app's review form uses words; the RPCs take 1–5 numbers. */
export function reviewToNumbers(details: { noise?: string; outlets?: string; wifi?: string }): ReviewNumbers {
  const noise = { quiet: 1, "very quiet": 1, chatter: 3, loud: 5 }[details.noise ?? ""];
  const outlets = { "no tables": 1, "a few tables": 3, "at a few tables": 3, "every table": 5, "at every table": 5 }[
    details.outlets ?? ""
  ];
  const wifi = { none: 1, slow: 1, medium: 3, fast: 5 }[details.wifi ?? ""];
  return { noise: noise ?? null, outlets: outlets ?? null, wifi: wifi ?? null };
}
